import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import DeleteFallbackImageModal from './DeleteFallbackImageModal';

/**
 * FallbackImageManager - Admin gallery component for managing fallback images.
 *
 * Allows the admin to upload images, browse uploaded files, mark one as the
 * active fallback image, and delete unused entries. Active selection is stored
 * in the `tryhackx-thumb-sliders.fallback_image` setting.
 */
export default class FallbackImageManager extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.files = [];
    this.loading = true;
    this.uploading = false;
    this.error = null;
    this.loadFiles();
  }
  view() {
    const mode = app.data.settings['tryhackx-thumb-sliders.fallback_mode'] || 'none';
    const activeFile = app.data.settings['tryhackx-thumb-sliders.fallback_image'] || '';
    return m("div", {
      className: "ThumbSlidersFallbackManager Form-group"
    }, m("label", null, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.title')), mode !== 'custom' && m("div", {
      className: "helpText ThumbSlidersFallbackManager__notice"
    }, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.not_active_mode')), m("div", {
      className: "ThumbSlidersFallbackManager__upload"
    }, m("label", {
      className: "Button"
    }, m("i", {
      className: "fas fa-upload Button-icon"
    }), m("span", null, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.upload_button')), m("input", {
      type: "file",
      className: "visually-hidden",
      accept: "image/webp,image/jpeg,image/png,image/gif,image/bmp,image/avif",
      disabled: this.uploading,
      onchange: e => this.uploadFile(e)
    })), this.uploading && m("span", {
      className: "ThumbSlidersFallbackManager__status"
    }, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.uploading'))), this.error && m("div", {
      className: "ThumbSlidersFallbackManager__error"
    }, this.error), this.loading ? m(LoadingIndicator, null) : this.files.length === 0 ? m("div", {
      className: "helpText"
    }, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.no_files')) : m("div", {
      className: "ThumbSlidersFallbackManager__grid"
    }, this.files.map(file => {
      const isActive = file.filename === activeFile;
      return m("div", {
        key: file.filename,
        className: 'ThumbSlidersFallbackManager__item' + (isActive ? ' ThumbSlidersFallbackManager__item--active' : ''),
        onclick: () => this.selectFile(file.filename)
        // Keyboard-operable toggle (it was a click-only <div>).
        ,
        role: "button",
        tabindex: "0",
        "aria-pressed": isActive ? 'true' : 'false',
        "aria-label": file.filename,
        onkeydown: e => {
          if (e.target !== e.currentTarget || e.key !== 'Enter' && e.key !== ' ') return;
          e.preventDefault();
          this.selectFile(file.filename);
        },
        title: file.filename
      }, m("img", {
        src: file.url,
        alt: "",
        loading: "lazy"
      }), isActive && m("span", {
        className: "ThumbSlidersFallbackManager__item-active"
      }, m("i", {
        className: "fas fa-check"
      })), m("button", {
        type: "button",
        className: "ThumbSlidersFallbackManager__item-delete",
        onclick: e => {
          e.stopPropagation();
          this.deleteFile(file);
        },
        title: app.translator.trans('tryhackx-thumb-sliders.admin.fallback.delete'),
        "aria-label": app.translator.trans('tryhackx-thumb-sliders.admin.fallback.delete')
      }, m("i", {
        className: "fas fa-times"
      })));
    })), activeFile && m("div", {
      className: "ThumbSlidersFallbackManager__clear"
    }, m("button", {
      type: "button",
      className: "Button Button--text",
      onclick: () => this.selectFile('')
    }, app.translator.trans('tryhackx-thumb-sliders.admin.fallback.clear_selection'))));
  }
  loadFiles() {
    this.loading = true;
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/thumb-sliders/uploads'
    }).then(res => {
      this.files = res && res.data || [];
      this.loading = false;
      m.redraw();
    }).catch(err => {
      this.error = this.extractError(err);
      this.loading = false;
      m.redraw();
    });
  }
  uploadFile(e) {
    const input = e.target;
    const file = input.files && input.files[0];
    if (!file) return;
    this.uploading = true;
    this.error = null;
    m.redraw();
    const formData = new FormData();
    formData.append('file', file);
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/thumb-sliders/uploads',
      serialize: raw => raw,
      body: formData
    }).then(res => {
      if (res && res.filename) {
        this.files.unshift(res);
        // Auto-select newly uploaded file
        this.selectFile(res.filename);
      }
      this.uploading = false;
      input.value = '';
      m.redraw();
    }).catch(err => {
      this.error = this.extractError(err);
      this.uploading = false;
      input.value = '';
      m.redraw();
    });
  }
  deleteFile(file) {
    // Confirm via a Flarum modal (not a native confirm() alert) so the prompt
    // matches the rest of the UI and can preview the image being removed.
    app.modal.show(DeleteFallbackImageModal, {
      file,
      ondelete: () => this.performDelete(file.filename)
    });
  }

  // Does the actual DELETE request and mirrors the local state. Returns the
  // promise so the modal can drive its loading state / surface errors.
  performDelete(filename) {
    return app.request({
      method: 'DELETE',
      url: app.forum.attribute('apiUrl') + '/thumb-sliders/uploads/' + encodeURIComponent(filename)
    }).then(() => {
      this.files = this.files.filter(f => f.filename !== filename);
      // Server clears the setting if the deleted file was active – mirror that locally
      if (app.data.settings['tryhackx-thumb-sliders.fallback_image'] === filename) {
        app.data.settings['tryhackx-thumb-sliders.fallback_image'] = '';
      }
      m.redraw();
    });
  }
  selectFile(filename) {
    this.error = null;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/settings',
      body: {
        'tryhackx-thumb-sliders.fallback_image': filename
      }
    }).then(() => {
      app.data.settings['tryhackx-thumb-sliders.fallback_image'] = filename;
      m.redraw();
    }).catch(err => {
      this.error = this.extractError(err);
      m.redraw();
    });
  }
  extractError(err) {
    try {
      if (err && err.response && err.response.errors && err.response.errors.length) {
        // Core's own errors often carry only a `code` (no detail/title) — fall
        // through instead of returning an empty, invisible message.
        const detail = err.response.errors.map(e => e.detail || e.title || '').filter(Boolean).join(' ');
        if (detail) return detail;
      }
      if (err && err.response && err.response.error) {
        return err.response.error;
      }
      if (err && err.alert && err.alert.content) return err.alert.content;
    } catch (_) {/* ignore */}
    // Not err.message: for a RequestError that is the raw response body.
    return app.translator.trans('tryhackx-thumb-sliders.admin.fallback.request_failed');
  }
}
flarum.reg.add('tryhackx-thumb-sliders', 'admin/components/FallbackImageManager', FallbackImageManager);